test_that("log_lik for FCOR student-t models works as expected", {
  withr::local_seed(179L)
  brms_setup("log_lik:180",
    ns <- 3
  )
  brms_setup("log_lik:181",
    nobs <- 4
  )
  brms_setup("log_lik:182",
    prep <- structure(list(ndraws = ns, nobs = nobs), class = "brmsprep")
  )
  brms_setup("log_lik:183",
    prep$data$Y <- rnorm(nobs)
  )
  brms_setup("log_lik:184",
    prep$dpars <- list(
      mu = matrix(rnorm(nobs * ns), nrow = ns),
      sigma = rgamma(ns, 2),
      nu = rgamma(ns, 5)
    )
  )
  brms_setup("log_lik:191",
    A <- matrix(rnorm(nobs^2), nobs, nobs)
  )
  brms_setup("log_lik:192",
    M <- t(A) %*% A + diag(nobs) * 0.1
  )
  brms_setup("log_lik:193",
    s_diag <- sqrt(diag(M))
  )
  brms_setup("log_lik:194",
    Mfcor <- M / (s_diag %*% t(s_diag))
  )
  brms_setup("log_lik:195",
    acframe <- data.frame(class = "fcor", cov = TRUE, stringsAsFactors = FALSE)
  )
  brms_setup("log_lik:196",
    class(acframe) <- c("acframe", "data.frame")
  )
  brms_setup("log_lik:197",
    prep$ac <- list(Mfcor = Mfcor, acframe = acframe)
  )
  brms_setup("log_lik:199",
    ll <- brms_adapt_log_lik("student_fcor", 1, prep = prep)
  )
  brms_setup("log_lik:203",
    ll_student <- matrix(0, ns, nobs)
  )
  brms_setup("log_lik:204",
    for (s in 1:ns) {
        df <- prep$dpars$nu[s]
        mu <- prep$dpars$mu[s, ]
        sigma <- prep$dpars$sigma[s]
        Sigma <- sigma^2 * prep$ac$Mfcor
        dfloo <- df + nobs - 1
        for (i in 1:nobs) {
            e_ic <- (prep$data$Y[-i] - mu[-i])
            Sigma_ic <- Sigma[-i, -i]
            Sigma_i_ic <- Sigma[i, -i]
            inv_Sigma_ic_e <- solve(Sigma_ic, e_ic)
            d_ic <- t(e_ic) %*% inv_Sigma_ic_e
            sigma_scale <- (df + d_ic)/dfloo
            schur <- Sigma[i, i] - Sigma_i_ic %*% solve(Sigma_ic, 
                Sigma_i_ic)
            mu_cond_i <- mu[i] + Sigma_i_ic %*% inv_Sigma_ic_e
            sigma_cond_i <- sqrt(sigma_scale * schur)
            y_i <- prep$data$Y[i]
            ll_student[s, i] <- dstudent_t(y_i, dfloo, mu_cond_i, 
                sigma_cond_i, log = TRUE)
        }
    }
  )
  brms_port("log_lik:230", "pass",
    "",
    expect_equal(ll, ll_student)
  )
})

test_that("log_lik for count and survival models works correctly", {
  withr::local_seed(233L)
  brms_adapt_brms_needs("extraDistr")
  brms_setup("log_lik:236",
    ns <- 25
  )
  brms_setup("log_lik:237",
    nobs <- 10
  )
  brms_setup("log_lik:238",
    trials <- sample(10:30, nobs, replace = TRUE)
  )
  brms_setup("log_lik:239",
    prep <- structure(list(ndraws = ns, nobs = nobs), class = "brmsprep")
  )
  brms_setup("log_lik:240",
    prep$dpars <- list(
      eta = matrix(rnorm(ns*nobs), ncol = nobs),
      shape = rgamma(ns, 4),
      xi = runif(ns, -1, 0.5),
      phi = rgamma(ns, 1)
    )
  )
  brms_setup("log_lik:246",
    prep$dpars$sigma <- 1 / prep$dpars$shape
  )
  brms_setup("log_lik:247",
    prep$dpars$nu <- prep$dpars$shape + 1
  )
  brms_setup("log_lik:248",
    prep$data <- list(
      Y = rbinom(nobs, size = trials, prob = rbeta(nobs, 1, 1)),
      trials = trials
    )
  )
  brms_setup("log_lik:252",
    i <- sample(nobs, 1)
  )
  brms_setup("log_lik:254",
    prep$dpars$mu <- inv_logit(prep$dpars$eta)
  )
  brms_setup("log_lik:255",
    ll_binom <- dbinom(
      x = prep$data$Y[i], prob = prep$dpars$mu[, i],
      size = prep$data$trials[i], log = TRUE
    )
  )
  brms_setup("log_lik:259",
    ll <- brms_adapt_log_lik("binomial", i, prep = prep)
  )
  brms_port("log_lik:260", "pass",
    "",
    expect_equal(ll, ll_binom)
  )
  brms_setup("log_lik:262",
    ll_beta_binom <- dbeta_binomial(
      x = prep$data$Y[i], size = prep$data$trials[i],
      mu = prep$dpars$mu[, i], phi = prep$dpars$phi, log = TRUE
    )
  )
  brms_setup("log_lik:266",
    ll <- brms_adapt_log_lik("beta_binomial", i, prep = prep)
  )
  brms_port("log_lik:267", "pass",
    "",
    expect_equal(ll, ll_beta_binom)
  )
  brms_value_mark()
  brms_setup("log_lik:270",
    ll <- brms_adapt_log_lik("discrete_weibull", i, prep = prep)
  )
  brms_port("log_lik:271", "pass",
    "",
    expect_equal(length(ll), ns)
  )
  brms_value_check("log_lik:271", "ll", "differs", {
    ll <- brms:::log_lik_discrete_weibull(i, prep = prep)
  }, msg_has = "DIFFERS: 25 values (0 NA, 17 infinite)")
  brms_setup("log_lik:273",
    prep$dpars$mu <- exp(prep$dpars$eta)
  )
  brms_setup("log_lik:274",
    ll_pois <- dpois(
      x = prep$data$Y[i], lambda = prep$dpars$mu[, i], log = TRUE
    )
  )
  brms_setup("log_lik:277",
    ll <- brms_adapt_log_lik("poisson", i, prep = prep)
  )
  brms_port("log_lik:278", "pass",
    "",
    expect_equal(ll, ll_pois)
  )
  brms_setup("log_lik:280",
    ll_nbinom <- dnbinom(
      x = prep$data$Y[i], mu = prep$dpars$mu[, i],
      size = prep$dpars$shape, log = TRUE
    )
  )
  brms_setup("log_lik:284",
    ll <- brms_adapt_log_lik("negbinomial", i, prep = prep)
  )
  brms_port("log_lik:285", "pass",
    "",
    expect_equal(ll, ll_nbinom)
  )
  brms_setup("log_lik:287",
    ll <- brms_adapt_log_lik("negbinomial2", i, prep = prep)
  )
  brms_port("log_lik:288", "pass",
    "",
    expect_equal(ll, ll_nbinom)
  )
  brms_setup("log_lik:290",
    ll_geo <- dnbinom(
      x = prep$data$Y[i], mu = prep$dpars$mu[, i],
      size = 1, log = TRUE
    )
  )
  brms_setup("log_lik:294",
    ll <- brms_adapt_log_lik("geometric", i, prep = prep)
  )
  brms_port("log_lik:295", "pass",
    "",
    expect_equal(ll, ll_geo)
  )
  brms_setup_not_run("log_lik:297", "ll_com_pois")
  # ll_com_pois <- brms:::dcom_poisson(
  #     x = prep$data$Y[i], mu = prep$dpars$mu[, i],
  #     shape = prep$dpars$shape, log = TRUE
  #   )
  brms_setup("log_lik:301",
    ll <- brms_adapt_log_lik("com_poisson", i, prep = prep)
  )
  brms_port("log_lik:302", "divergence",
    paste0(
      "a known parameterization divergence (findings R6, fix round ",
      "2): the reference brms:::dcom_poisson() takes mu = ",
      "lambda^(1 / shape), while frmtmb's compois mu is the mean ",
      "(RTMB::dcompois2), so the two log densities differ at the ",
      "same numbers (max 94 log units at the block's seed; at mu = ",
      "3, shape = 2 brms's mean is 2.737, ",
      "dev/remeasure-bin2-probe2.R section 6). The row's text ",
      "reaches brms:::, so the harness records it and does not run ",
      "it"),
    expect_equal(ll, ll_com_pois)
  )
  brms_setup("log_lik:304",
    ll_exp <- dexp(
      x = prep$data$Y[i], rate = 1 / prep$dpars$mu[, i], log = TRUE
    )
  )
  brms_setup("log_lik:307",
    ll <- brms_adapt_log_lik("exponential", i, prep = prep)
  )
  brms_port("log_lik:308", "pass",
    "",
    expect_equal(ll, ll_exp)
  )
  brms_setup("log_lik:310",
    ll_gamma <- dgamma(
      x = prep$data$Y[i], shape = prep$dpars$shape,
      scale = prep$dpars$mu[, i] / prep$dpars$shape,
      log = TRUE
    )
  )
  brms_setup("log_lik:315",
    ll <- brms_adapt_log_lik("gamma", i, prep = prep)
  )
  brms_port("log_lik:316", "pass",
    "",
    expect_equal(ll, ll_gamma)
  )
  brms_setup("log_lik:318",
    scale <- prep$dpars$mu[, i] / gamma(1 - 1 / prep$dpars$nu)
  )
  brms_setup("log_lik:319",
    ll_frechet <- dfrechet(
      x = prep$data$Y[i], shape = prep$dpars$nu,
      scale = scale, log = TRUE
    )
  )
  brms_setup("log_lik:323",
    ll <- brms_adapt_log_lik("frechet", i, prep = prep)
  )
  brms_port("log_lik:324", "pass",
    "",
    expect_equal(ll, ll_frechet)
  )
  brms_setup("log_lik:326",
    ll_invgauss <- dinv_gaussian(
      x = prep$data$Y[i], shape = prep$dpars$shape,
      mu = prep$dpars$mu[, i], log = TRUE
    )
  )
  brms_setup("log_lik:330",
    ll <- brms_adapt_log_lik("inverse.gaussian", i, prep = prep)
  )
  brms_port("log_lik:331", "pass",
    "",
    expect_equal(ll, ll_invgauss)
  )
  brms_setup("log_lik:333",
    ll_weibull <- dweibull(
      x = prep$data$Y[i], shape = prep$dpars$shape,
      scale = prep$dpars$mu[, i] / gamma(1 + 1 / prep$dpars$shape),
      log = TRUE
    )
  )
  brms_setup("log_lik:338",
    ll <- brms_adapt_log_lik("weibull", i, prep = prep)
  )
  brms_port("log_lik:339", "pass",
    "",
    expect_equal(ll, c(ll_weibull))
  )
  brms_setup("log_lik:342",
    prep$family$link <- "identity"
  )
  brms_setup("log_lik:343",
    prep$data$Y[i] <- 0
  )
  brms_setup("log_lik:344",
    ll_gen_extreme_value <- SW(dgen_extreme_value(
      x = prep$data$Y[i], mu = prep$dpars$mu[, i],
      sigma = prep$dpars$sigma, xi = prep$dpars$xi, log = TRUE
    ))
  )
  brms_setup("log_lik:348",
    ll <- SW(brms_adapt_log_lik("gen_extreme_value", i, prep = prep))
  )
  brms_port("log_lik:349", "divergence",
    paste0(
      "frmtmb's gen_extreme_value() log density is finite and ",
      "steep outside the support (-1.0e150 at y = 0, mu 1, sigma ",
      "0.1, xi 0.3), so the optimizer is turned back and a mixture ",
      "component adds nothing there; brms's dgen_extreme_value() ",
      "is NaN. Inside the support the two agree (-1.55396; ",
      "dev/rel071-gev-probe.R). Lane famuni's documented choice"),
    expect_equal(ll, ll_gen_extreme_value)
  )
})

